"""LLM-based extraction (phase 2 arm; NOT yet evaluated in this repo).

Same output as `extract.extract()` (a ClinicalNote), so every metric and
safety check works unchanged. Design choices that matter clinically:

* The model must quote the utterance each fact comes from (`evidence`), and
  `validate_against_transcript()` drops any fact whose quote is not in the
  transcript: an LLM cannot add a drug nobody said.
* Codes are never generated by the LLM; it returns our internal concept /
  drug ids from a closed list, and SNOMED codes come from the lexicon.
* `hybrid()` keeps the rule extractor as a safety net: allergies and
  medications found by rules are never dropped by the LLM.

Backends: any callable `complete(prompt: str) -> str`. `bedrock_complete()`
targets AWS Bedrock in ap-south-1 (Mumbai) so data stays in India.
"""
from __future__ import annotations

import json
import re
from typing import Callable

from .extract import extract as rule_extract
from .lexicon import concepts, drugs
from .schema import Allergy, ClinicalNote, Finding, Medication, Turn, Vital

PROMPT = """You are a clinical scribe for an Indian outpatient clinic. The consult below is in Hinglish
(Hindi-English, Roman and/or Devanagari script). Extract ONLY what was said. Return JSON:

{{"findings": [{{"concept_id": str, "present": bool, "duration_days": number|null, "is_diagnosis": bool, "evidence": str}}],
 "allergies": [{{"concept_id": str, "evidence": str}}],
 "medications": [{{"drug_id": str, "dose_value": number|null, "dose_unit": "mg"|"ml"|"mcg"|"puff"|null,
                  "frequency": "OD"|"BD"|"TDS"|"QID"|"HS"|"SOS"|null, "duration_days": number|null, "evidence": str}}],
 "vitals": [{{"name": "bp"|"temperature"|"pulse"|"spo2"|"fasting_glucose", "value": number, "value2": number|null, "evidence": str}}]}}

Rules:
- concept_id must be one of: {concepts}
- drug_id must be one of: {drugs}. Map brand names (Dolo, Crocin -> paracetamol; Azithral -> azithromycin; Glycomet -> metformin).
- "present": false for symptoms the patient denies ("khansi nahi hai", "No fever").
- is_diagnosis: true only for the doctor's assessment; a patient's known condition is history (false).
- Do NOT record a drug the doctor says NOT to take ("Brufen mat lena").
- 1-0-1 means BD, 1-1-1 means TDS, 0-0-1 means HS. "zarurat pade toh"/"jab dard ho" means SOS.
- evidence: copy the exact words of the utterance the fact comes from.
- Return JSON only.

Consult:
{transcript}
"""


def build_prompt(turns: list[Turn]) -> str:
    return PROMPT.format(concepts=", ".join(sorted(concepts())), drugs=", ".join(sorted(drugs())),
                         transcript="\n".join(f"{t.speaker.upper()}: {t.text}" for t in turns))


def _parse_json(text: str) -> dict:
    m = re.search(r"\{.*\}", text, re.S)
    if not m:
        raise ValueError("no JSON object in LLM output")
    return json.loads(m.group(0))


def _norm(s: str) -> str:
    return re.sub(r"\s+", " ", re.sub(r"[^\wऀ-ॿ ]", " ", s.lower())).strip()


def validate_against_transcript(data: dict, turns: list[Turn]) -> tuple[dict, list[str]]:
    """Drop facts with unknown ids or evidence not found in the transcript."""
    corpus = _norm(" ".join(t.text for t in turns))
    cdb, ddb = concepts(), drugs()
    dropped: list[str] = []
    out: dict = {"findings": [], "allergies": [], "medications": [], "vitals": []}
    for key, idfield, db in (("findings", "concept_id", cdb), ("allergies", "concept_id", cdb), ("medications", "drug_id", ddb), ("vitals", None, None)):
        for item in data.get(key, []) or []:
            ev = _norm(str(item.get("evidence", "")))
            if idfield and item.get(idfield) not in db:
                dropped.append(f"{key}: unknown id {item.get(idfield)!r}")
                continue
            if not ev or ev not in corpus:
                dropped.append(f"{key}: evidence not in transcript for {item.get(idfield) or item.get('name')}")
                continue
            out[key].append(item)
    return out, dropped


def llm_extract(turns: list[Turn], complete: Callable[[str], str], patient_id: str = "anon",
                encounter_id: str = "enc", date: str = "") -> tuple[ClinicalNote, list[str]]:
    data, dropped = validate_against_transcript(_parse_json(complete(build_prompt(turns))), turns)
    cdb = concepts()
    n = ClinicalNote(patient_id, encounter_id, date)
    n.findings = [Finding(f["concept_id"], cdb[f["concept_id"]].category if cdb[f["concept_id"]].category != "allergy" else "condition",
                          bool(f.get("present", True)), f.get("duration_days"), "doctor" if f.get("is_diagnosis") else "patient",
                          bool(f.get("is_diagnosis")), f["evidence"]) for f in data["findings"]]
    n.allergies = [Allergy(a["concept_id"], a["evidence"]) for a in data["allergies"]]
    n.medications = [Medication(m["drug_id"], m.get("dose_value"), m.get("dose_unit"), m.get("frequency"),
                                m.get("duration_days"), m["evidence"]) for m in data["medications"]]
    n.vitals = [Vital(v["name"], v["value"], v.get("value2"), "", v["evidence"]) for v in data["vitals"]]
    return n, dropped


def hybrid(turns: list[Turn], complete: Callable[[str], str], **kw) -> tuple[ClinicalNote, list[str]]:
    """LLM note, with rule-found allergies and medications added back if the LLM missed them."""
    llm, dropped = llm_extract(turns, complete, **kw)
    rules = rule_extract(turns, **kw)
    have_a = {a.concept_id for a in llm.allergies}
    llm.allergies += [a for a in rules.allergies if a.concept_id not in have_a]
    have_m = {m.drug_id for m in llm.medications}
    llm.medications += [m for m in rules.medications if m.drug_id not in have_m]
    return llm, dropped


def bedrock_complete(model_id: str, region: str = "ap-south-1", max_tokens: int = 2000) -> Callable[[str], str]:
    """AWS Bedrock Converse API client (requires boto3 and AWS credentials)."""
    import boto3

    client = boto3.client("bedrock-runtime", region_name=region)

    def complete(prompt: str) -> str:
        r = client.converse(modelId=model_id, messages=[{"role": "user", "content": [{"text": prompt}]}],
                            inferenceConfig={"maxTokens": max_tokens, "temperature": 0})
        return r["output"]["message"]["content"][0]["text"]

    return complete
